struct ListNode {
    int val;
    ListNode *next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode *next) : val(x), next(next) {}
};

ListNode* reverseKGroup(ListNode* head, int k) {
    if (head == nullptr || k == 1) return head;

    int len = 0;
    ListNode *cur = head;
    while (cur != nullptr) {
        len++;
        cur = cur->next;
    }

    ListNode dummy(0);
    dummy.next = head;
    ListNode *prev = &dummy;
    cur = head;

    while (len >= k) {
        for (int i = 1; i < k; i++) {
            ListNode *temp = cur->next;
            cur->next = temp->next;
            temp->next = prev->next;
            prev->next = temp;
        }
        prev = cur;
        cur = cur->next;
        len -= k;
    }

    return dummy.next;
}
```

