public int maximalRectangle(char[][] matrix) {
    if (matrix.length == 0) return 0;

    int m = matrix.length;
    int n = matrix[0].length;
    int[] height = new int[n + 1];
    int maxArea = 0;

    for (int i = 0; i < m; ++i) {
        Stack<Integer> s = new Stack<>();
        for (int j = 0; j <= n; ++j) {
            if (j < n) {
                height[j] = matrix[i][j] == '1' ? height[j] + 1 : 0;
