            while (!s.empty() && height[j] < height[s.peek()]) {
                int h = height[s.pop()];
                int w = s.empty() ? j : j - s.peek() - 1;
                maxArea = Math.max(maxArea, h * w);
            }
            s.push(j);
        }
    }

    return maxArea;
}
