    vector<vector<int>> dp(m, vector<int>(n));

    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            if(i == m-1 && j == n-1){
                dp[i][j] = min(0, dungeon[i][j]);
