        int currCourse = q.front();
        q.pop();
        numCourses--;

        for (int nextCourse : adj[currCourse]) {
            inDegree[nextCourse]--;
            if (inDegree[nextCourse] == 0) q.push(nextCourse);
        }
    }

    return numCourses == 0;
}
