        PriorityQueue<int[]> pq = new PriorityQueue<>((p1, p2) -> p1[0] != p2[0] ? p1[0] - p2[0] : p1[1] - p2[1]);
        pq.offer(new int[]{0, 0});

        while (!pq.isEmpty()) {
            int cur_dist = pq.peek()[0], cur_d = pq.peek()[1];
            String cur_path = pq.poll()[2];
            int x = ball[0], y = ball[1];
