class Solution {
public:
    void leftBoundary(TreeNode* node, vector<int>& boundary) {
        if (!node || (!node->left && !node->right)) return;
        boundary.push_back(node->val);
        if (node->left) leftBoundary(node->left, boundary);
        else leftBoundary(node->right, boundary);
    }

    void rightBoundary(TreeNode* node, vector<int>& boundary) {
        if (!node || (!node->left && !node->right)) return;
        if (node->right) rightBoundary(node->right, boundary);
        else rightBoundary(node->left, boundary);
        boundary.push_back(node->val);
    }

    void leaves(TreeNode* node, vector<int>& boundary) {
        if (!node) return;
        if (!node->left && !node->right) {
            boundary.push_back(node->val);
        }
        leaves(node->left, boundary);
        leaves(node->right, boundary);
    }

    vector<int> boundaryOfBinaryTree(TreeNode* root) {
        vector<int> res;
        if (!root) return res;
        res.push_back(root->val);
        leftBoundary(root->left, res);
        leaves(root, res);
        rightBoundary(root->right, res);
        return res;
    }
};
