int regionsBySlashes(std::vector<std::string>& grid) {
    int n = grid.size();
    std::vector<std::vector<int>> graph(n * 3, std::vector<int>(n * 3, 0));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == '/') {
                graph[i * 3][j * 3 + 2] = graph[i * 3 + 1][j * 3 + 1] = graph[i * 3 + 2][j * 3] = 1;
