    for (int[] lamp : lamps) {
        lampRows.add(lamp[0]);
        lampCols.add(lamp[1]);
        lampLeftDiag.add(lamp[0] - lamp[1]);
        lampRightDiag.add(lamp[0] + lamp[1]);
