public int[] maxSizeSubsequenceSumQueries(int[] nums, int[] queries) {
    Arrays.sort(nums);
    int[] prefixSums = new int[nums.length + 1];
    for (int i = 0; i < nums.length; ++i) {
        prefixSums[i + 1] = prefixSums[i] + nums[i];
    }

    int[] answer = new int[queries.length];
    for (int i = 0; i < queries.length; ++i) {
        int idx = Arrays.binarySearch(prefixSums, queries[i]);
        if (idx < 0) {
            idx = -idx - 1;
        }
        answer[i] = idx - 1;
    }

    return answer;
}
