int getLastMoment(int n, int k, vector<vector<int>>& time) {
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> left, right;
    for (int i = 0; i < k; i++) {
        left.push({time[i][0] + time[i][2], i});
    }

    while (n) {
        while (!right.empty() && right.top().first <= left.top().first) {
            auto rightTop = right.top(); right.pop();
            left.push({rightTop.first + time[rightTop.second][0] + time[rightTop.second][2], rightTop.second});
        }
        auto leftTop = left.top(); left.pop();
        time[leftTop.second][2] += time[leftTop.second][3] + time[leftTop.second][0] + time[leftTop.second][1];
        right.push({leftTop.first + time[leftTop.second][1], leftTop.second});
        n--;
    }

    int lastMoment = -1;
    while (!right.empty()) {
        lastMoment = max(lastMoment, time[right.top().second][2]);
        right.pop();
    }
    return lastMoment;
}
