int minTimeToEatGrains(std::vector<int>& hens, std::vector<int>& grains) {
    std::sort(hens.begin(), hens.end());
    std::sort(grains.begin(), grains.end());
    int left = 0, right = 1e9;

    while (left < right) {
        int mid = left + (right - left) / 2;
        bool can_eat = true;
        int i = 0;

        for (int grain : grains) {
            if (i >= hens.size()) {
                can_eat = false;
                break;
            }

            while (i < hens.size() && hens[i] < grain - mid) {
                ++i;
            }

            if (i >= hens.size() || hens[i] > grain + mid) {
                can_eat = false;
                break;
            }

            ++i;
        }

        if (can_eat) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
}
