public class SerejaArrangementNumbers {

    int N = (int) 1e5 + 10;

    void solve() {
        int n = in.nextInt(), m = in.nextInt();
        int[] q = new int[m], w = new int[m];
        for (int i = 0; i < m; i++) {
            q[i] = in.nextInt();
            w[i] = in.nextInt();
        }

        int lb = 0, ub = m + 1;
        while (ub - lb > 1) {
            int mid = (lb + ub) >> 1;
            long min;
            if (mid % 2 == 1) {
                min = (long) mid * (mid - 1) / 2;
            } else {
                min = (long) mid * (mid - 1) / 2 + (mid / 2 - 1);
            }
            if (min <= n - 1) lb = mid;
            else ub = mid;
        }

        Integer[] ids = new Integer[m];
        Arrays.setAll(ids, i -> i);
        Arrays.sort(ids, (i, j) -> -Integer.compare(w[i], w[j]));

        long ans = 0;
        for (int i = 0; i < Math.min(lb, n); i++) ans += w[ids[i]];
        out.println(ans);
