        int sgn;

        public P(long k, long b)
        {
            super();
            if(b < 0 && k < 0)
                sgn = 1;
            else if(b > 0 && k > 0)
                sgn = 1;
            else if(b == 0)
                sgn = 1;
            else
                sgn = 2;

            this.k = Math.abs(k);
            this.b = Math.abs(b);
        }

