		for(int x : c)
			cnt[x]++;

		int minLeafs = (n + 1) >> 1;
		if(cnt[1] < minLeafs || cnt[n] != 1){
			System.out.println("NO");
			return;
		}
		else{
			leafs = cnt[1];
			inter = n - cnt[1];
			subtree = new int[inter];
