			for(int x : c)
				if(x != 1)
					subtree[inter++] = x;
			Arrays.sort(subtree);
			//System.out.println(Arrays.toString(subtree));
			dp = new boolean[leafs + 1][1<<inter];
			done = new boolean[leafs + 1][1<<inter];
