        self.data = data
        self.height=0
        self.left = None  # left node for 0
        self.right = None  # right node for 1
class BinaryTrie:
    def __init__(self):
        self.root = Node(0)
    def insert(self, pre_xor):
        self.temp = self.root
        for i in range(31, -1, -1):
            val = pre_xor & (1 << i)
            if val==0:
                if not self.temp.right:
                    self.temp.right = Node(0)
                self.temp = self.temp.right
            elif val>=1:
                if not self.temp.left:
                    self.temp.left = Node(0)
                self.temp = self.temp.left
    def do(self,temp):
        if not temp:
            return 0
        ter=temp
        temp.height=self.do(ter.left)+self.do(ter.right)
        if temp.height==0:
            temp.height+=1
        return temp.height
    def query(self, xor):
        self.temp = self.root
        cur=0
        i=31
        while(i>-1):
            val = xor & (1 << i)
            if not self.temp:
                return cur
            if val>=1:
                self.opp = self.temp.right
                if self.temp.left:
                    self.temp = self.temp.left
                else:
                   return cur
            else:
                self.opp=self.temp.left
                if self.temp.right:
                   self.temp = self.temp.right
                else:
                   return cur
            if self.temp.height==pow(2,i):
                cur+=1<<(i)
                self.temp=self.opp
            i-=1
        return cur
