	final static int MAXN = 100000+5;
	int[] graphA = new int[MAXN];
	int[] graphB = new int[MAXN];
	int[] match = new int[MAXN];
	boolean[] used = new boolean[MAXN];

	class Segment {
		public int low;
		public int high;
		public int man;
	}

	public void run() {
		int n = in.readInt(); // right side
		int m = in.readInt(); // left side

		Segment[] segs = new Segment[m];
		for (int l = 0; l < m; l++) {
			int r = n-in.readInt();
			int c = in.readInt()-1;
			segs[l] = new Segment();
			segs[l].low = Math.min(r,c);
			segs[l].high = Math.max(r,c);
			segs[l].man = l;
		}
		Arrays.sort(segs, new Comparator<Segment>() {
			@Override
			public int compare(Segment o1, Segment o2) {
				return o1.low - o2.low;
			}
		});

		Queue<Segment> Q = new PriorityQueue<Segment>(m, new Comparator<Segment>() {
			@Override
			public int compare(Segment o1, Segment o2) {
				return o1.high - o2.high;
			}
		});
		List<Integer> assignments = new ArrayList<Integer>();

		int i = 0;
		for (int low = 0; low < n; low++) {
			while (i < m && segs[i].low == low) {
				Q.add(segs[i]);
				i++;
			}
			if (!Q.isEmpty()) {
				assignments.add(Q.poll().man);
				while (!Q.isEmpty() && Q.peek().high <= low)
					Q.poll();
			}
		}

