    public void solve(int testNumber, FastScanner in, FastPrinter out) {
        in.next();
        char[] s = in.next().toCharArray();
        int n = s.length;
        if ((n & 1) == 1) {
            out.println(0);
            return;
        }
        int[] dp = new int[n / 2 + 1];
        int[] next = new int[n / 2 + 1];
        dp[0] = 1;
        int count = 0;
        for (int i1 = 0; i1 < n; i1++) {
            char e = s[i1];
