                ++count;
                int left = i1 - n / 2;
                int right = i1 / 2;
                if (left < 0) left = 0;
                if ((i1 & 1) == 1) {
                    dp[(i1 + 1) / 2] += dp[(i1 + 1) / 2 - 1];
                }
                for (int i = right; i > left; i--) {
