    int[] bit = new int[N];

    void solve() {
        n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();

        int[] cnt = new int[N];
        for (int i = 0; i < n; i++) cnt[a[i]]++;
        int[][] g = new int[N][];
        for (int i = 0; i < N; i++) {
            g[i] = new int[cnt[i]];
            cnt[i] = 0;
        }
        for (int i = 0; i < n; i++) {
            g[a[i]][cnt[a[i]]++] = i;
        }

        int prev = 0;
        for (int v = 0; v < N; v++) {
            if (cnt[v] == 0) continue;
            int p = lowerBound(g[v], prev);
            if (p == cnt[v]) p = 0;
            for (int i = 0; i < cnt[v]; i++) {
                move(prev, g[v][p]);
                if (i > 0) ans--;
                prev = g[v][p];
                p++;
                if (p >= cnt[v]) p -= cnt[v];
            }
            for (int i = 0; i < cnt[v]; i++) {
                add(g[v][i]);
            }
        }
        out.println(ans);
    }

    void move(int a, int b) {
        if (a <= b) {
            ans += (b - a + 1) - sum(a, b);
        } else {
            ans += (n - a) - sum(a, n - 1);
            ans += (b + 1) - sum(0, b);
        }
    }

    void add(int i) {
