  private int[] dp;
  private int N, exp = -1, n;

  public void solve(InputReader in) {
    n = in.nextInt();
    N = (1 << (n + 1)) - 1;

    dp = new int[N * 2];
    Arrays.fill(dp, 0);
    for (int i = 2; i <= N; ++i) {
      dp[i] = in.nextInt() + dp[i / 2];
      if (dp[i] > exp) exp = dp[i];
    }

    dfs(1);

    int ans = 0;
    for (int i = 2; i <= N; ++i) {
      ans += dp[i];
    }
    System.out.println(ans);
  }

  private int dfs(int cur) {
    if (cur > N) return 0;
    int l = cur << 1, r = l | 1;
    if (cur > 1) {
      if (l >= N) {
        dp[cur] = exp - dp[cur];
      } else {
        dp[cur] = Math.min(dfs(l), dfs(r));
        dp[l] -= dp[cur];
        dp[r] -= dp[cur];
      }
    } else {
      dfs(l);
      dfs(r);
    }
    return dp[cur];
  }
}

