        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] v = new int[n];
            int[] d = new int[n];
            int[] p = new int[n];
            for (int i = 0; i < n; i++) {
                v[i] = in.readInt();
                d[i] = in.readInt();
                p[i] = in.readInt();
            }
            boolean[] inQueue = new boolean[n];
            IntList answer = new IntArrayList();
            Arrays.fill(inQueue, true);
            for (int i = 0; i < n; i++) {
                if (inQueue[i]) {
                    answer.add(i + 1);
                    IntList runAway = new IntArrayList();
                    inQueue[i] = false;
                    int current = v[i];
                    for (int j = i + 1; j < n && current > 0; j++) {
                        if (inQueue[j]) {
                            p[j] -= current--;
                            if (p[j] < 0) {
                                inQueue[j] = false;
                                runAway.add(j);
                            }
                        }
                    }
                    for (int l = 0; l < runAway.size(); l++) {
                        int j = runAway.get(l);
                        for (int k = j + 1; k < n; k++) {
                            if (inQueue[k]) {
                                p[k] -= d[j];
                                if (p[k] < 0) {
                                    inQueue[k] = false;
                                    runAway.add(k);
                                }
