        if (x == 2) {
            out.println(-1);
        } else if (n == 1) {
            out.println(x - 1);
        } else {
            int tmp = n + 1;
            for (int i = 2; i * i <= tmp; ++i)
                if (tmp % i == 0) {
                    out.println(-1);
                    return;
                }
            tmp = n;
            int[] divs = new int[100];
            int ndivs = 0;
            for (int i = 2; i * i <= tmp; ++i)
