    private int gcd(int a, int b) {
        while (b > 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private long pow(long a, long k, long b) {
        if (k == 0) {
            return 1 % b;
        }
        if (k % 2 == 0) {
            return pow(a * a % b, k / 2, b);
        }
        return a * pow(a, k - 1, b) % b;
    }
