            for (i = M - 2; i >= 0; --i) {
                leastReq[i] = Math.max(leastReq[i], leastReq[i + 1] + 1);
            }

            //System.err.println(Arrays.toString(suffix));
            //System.err.println(Arrays.toString(leastReq));

            int[] ans = new int[M];
            if (recurse(0, 0, 0, ans, leastReq, suffix)) {
                hp.println(hp.joinElements(ans));
            } else {
                hp.println(-1);
            }
        }

        timer.cancel();
        hp.flush();
    }

    boolean recurse(int idx, int start, int end, int[] ans, int[] leastReq, long[] maxFillable) {
        //System.err.println(idx + " " + start + " -> " + end);

        if (end > N) return false;
        else if (idx >= M) {
            return end == N;
        }

        int maxOffered = N - start, unfilled = N - end;
        if (maxOffered < leastReq[idx] || unfilled > maxFillable[idx]) {
            return false;
        } else {
            for (int i = start; i <= end; ++i) {
                if (recurse(idx + 1, i + 1, Math.max(end, i + L[idx]),
                        ans, leastReq, maxFillable)) {
                    ans[idx] = i + 1;
                    return true;
                }
            }
            System.exit(7 / 0);
            return false;
        }
    }
}

