        int m = scanner.nextInt();
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int[] d = new int[a + b];

        Arrays.fill(d, -1);
        d[0] = 0;
        int cur = 0, limit = 0;
        while (cur - b != 0) {
            if (cur - b > 0) {
                cur -= b;
            } else {
                limit = Integer.max(limit, cur + a);
                cur += a;
            }
            d[cur] = limit;
        }
        long ans = 0;
        if (a + b > m) {
            for (int i = 0; i <= m; ++i) {
                if (d[i] != -1 && m >= d[i]) {
                    ans += m - d[i] + 1;
                }
            }
        } else {
            for (int i = 0; i < a + b; ++i) {
                if (d[i] != -1) {
                    ans += m - d[i] + 1;
                }
            }
            // a+b ... m
            int g = gcd(a, b);
            int l = a + b;
            int r = m - m % g;
            int count = (r - l) / g + 1;
            int first = (m - l + 1);
            int last = (m - r + 1);
            ans += (long) (first + last) * count / 2;
        }
        writer.println(ans);

