            if (a[m]<element){
                l=m+1;
            }else{
                h=m;
            }
        }

        if (a[h]<element){
            return -1;
        }
        return h;
    }
    private static int binarySearchFindLastOccurrence(long[] a,long element){
        int l=0;
        int h=a.length-1;

        while(l<=h){
            int m=(h+l)/2;
            if (a[m]<element){
                l=m+1;
            }else if (a[m]==element){
                if (m==a.length-1){
                    return m;
                }
                if (element<a[m+1]) {
                    return m;
                }else{
                    l=m+1;
                }
            }else{
                h=m-1;
            }
        }

        if (h>=0 && h<=a.length-1 && a[h]<element){
            return h;
        }else{
            return -1;
        }
    }
